Пример 1: Подсчет количества четных элементов в массиве
```pascal
var
    a: array[1..10] of integer;
    i, count: integer;
begin
    { Заполнение массива }
    randomize;
    for i := 1 to 10 do
        a[i] := random(100);

    { Вывод массива }
    write('Массив: ');
    for i := 1 to 10 do
        write(a[i], ' ');

    { Подсчет четных элементов }
    count := 0;
    for i := 1 to 10 do
        if a[i] mod 2 = 0 then
            count := count + 1;

    { Вывод результата }
    writeln('Количество четных элементов: ', count);
end.
```

Пример 2: Сумма элементов на четных позициях
