Пример 4: Проверка наличия элемента в массиве

```pascal
var
    a: array[1..6] of integer = (3, 7, 2, 9, 5, 1);
    x, found: integer;
    i: integer;
begin
    write('Введите искомое число: ');
    readln(x);

    found := -1;
    for i := 1 to 6 do
        if a[i] = x then
        begin
            found := i;
            break;
        end;

    if found = -1 then
